div.style:
position:absolute; top:100%; left:0; z-index:9999;
                                                    width:100%; max-height:260px; overflow-y:auto;
                                                    border:1px solid #d0d9f5; border-radius:8px;
                                                    background:#fff; box-shadow:0 6px 20px rgba(0,0,0,0.12);
                                                    margin-top:4px;

